INSERT INTO `biens` (`id_biens`, `nom_biens`, `rue_biens`, `superficie_biens`, `description_biens`, `animal_biens`, `nb_couchage`, `id_commune`, `id_type_biens`, `is_hidden`, `created_by_id`, `created_by_name`, `unavailable_weeks`, `validated`, `validated_by`, `validated_at`) VALUES
(1, 'Appartement Vue Tour Eiffel', '5 Avenue Anatole France', 0, '', 0, 0, 30438, 1, 0, 1, 'Pierre Dubois', NULL, 1, 3, '2025-12-08 13:55:33'),
(2, 'Villa Méditerranée', '25 Corniche Kennedy', 180, 'Superbe villa face à la mer avec piscine privée. 4 chambres, jardin de 500m². Vue panoramique sur la Méditerranée. Accès direct à la plage.', 1, 8, 4440, 3, 0, 2, 'Marie Moreau', NULL, 1, 3, '2025-12-06 13:55:47'),
(3, 'Loft Design Lyon', '15 Quai Saint-Antoine', 95, 'Loft contemporain dans le vieux Lyon. Style industriel avec poutres apparentes. Proche des restaurants et commerces.', 0, 6, 28153, 7, 0, 3, 'Thomas Leroy', NULL, 1, 2, '2025-11-12 13:56:05'),
(4, 'Maison Bordelaise', '42 Rue Sainte-Catherine', 140, 'Belle maison bordelaise rénovée avec jardin. Proche des châteaux viticoles. Parfaite pour découvrir la région des vins.', 1, 6, 12679, 2, 0, 4, 'Julie Petit', NULL, 1, 1, '2025-12-01 13:56:24'),
(5, 'Studio Nice Centre', '8 Promenade des Anglais', 35, 'Studio cosy avec balcon vue mer. À deux pas de la plage et du centre-ville. Tout équipé pour 2 personnes.', 0, 2, 2050, 4, 0, 5, 'Marc Rousseau', NULL, 1, 1, '2025-12-09 13:55:14'),
(6, 'Chalet Annecy', '30 Avenue d\'Albigny', 120, 'Chalet traditionnel savoyard avec vue sur le lac d\'Annecy et les montagnes. Cheminée, terrasse, 3 chambres. Idéal été comme hiver.', 1, 7, 30171, 5, 0, 6, 'Emma Blanc', NULL, 1, 2, '2025-12-04 14:00:09'),
(7, 'Penthouse Marseille', '100 Boulevard Michelet', 160, 'Penthouse de luxe dernier étage avec terrasse de 80m². Vue 360° sur Marseille et la mer. Standing exceptionnel.', 0, 6, 4440, 8, 0, 7, 'Lucas Garnier', NULL, 1, 3, '2025-09-30 12:59:43'),
(8, 'Cottage Provençal', '5 Chemin de la Calade', 110, 'Charmant cottage entouré d\'oliviers. Piscine chauffée, jardin méditerranéen. Calme absolu, idéal détente.', 1, 5, 33677, 9, 0, 8, 'Léa Faure', NULL, 1, 1, '2025-10-24 12:59:21'),
(9, 'Appartement Capitole Toulouse', '12 Place du Capitole', 68, 'Appartement rénové en plein cœur de Toulouse. Vue sur la place, proche métro et commerces. Équipement haut de gamme.', 0, 4, 11719, 1, 0, 9, 'Hugo Andre', NULL, 1, 3, '2025-12-02 13:59:02'),
(10, 'Villa Basque Biarritz', '18 Avenue Edouard VII', 200, 'Superbe villa basque à 100m de la plage. 5 chambres, piscine, grand jardin. Architecture typique, tout confort.', 1, 10, 26152, 3, 0, 10, 'Chloé Lambert', NULL, 1, 1, '2025-12-08 13:58:37'),
(11, 'Loft Strasbourg', '22 Quai des Bateliers', 88, 'Loft moderne quartier de la Petite France. Cachet alsacien, poutres et pierres apparentes. Proche cathédrale.', 0, 4, 27304, 7, 0, 1, 'Pierre Dubois', NULL, 1, 3, '2025-11-04 13:58:18'),
(12, 'Maison Nantaise', '35 Rue de la Loire', 125, 'Maison de maître nantaise avec jardin arboré. 4 chambres, parking privé. Quartier résidentiel calme.', 1, 8, 16756, 2, 0, 2, 'Marie Moreau', NULL, 1, 3, '2025-12-03 13:57:57'),
(13, 'Studio Montpellier', '9 Rue de l\'Université', 32, 'Studio étudiant rénové, proche fac et tramway. Idéal pour courts ou longs séjours. Tout équipé.', 0, 2, 13339, 4, 0, 11, 'Events Pro SARL', NULL, 1, 2, '2025-12-07 13:57:39'),
(14, 'Résidence Toulon Port', '14 Quai Cronstadt', 78, 'Appartement dans résidence sécurisée vue port. 2 chambres, balcon, parking. Proche plages et centre.', 0, 5, 33677, 10, 0, 3, 'Thomas Leroy', NULL, 1, 1, '2025-10-21 12:57:08'),
(15, 'Chalet Alpes', '7 Route du Semnoz', 150, 'Grand chalet familial station de ski. 6 chambres, sauna, cheminée. Accès direct pistes l\'hiver.', 1, 12, 30171, 5, 0, 12, 'Vacances Corp SAS', NULL, 1, 3, '2025-12-12 13:56:56');
