INSERT INTO `evenement` (`id_evenement`, `nom_evenement`, `date_debut_evenement`, `date_fin_evenement`, `description_evenement`, `id_commune`, `id_type_evenement`) VALUES
(1, 'Festival de Cannes', '2025-05-13', '2025-05-24', 'Le plus prestigieux festival de cinéma au monde. Tapis rouge, projections, rencontres avec les stars.', 1816, 1),
(2, 'Fête de la Musique Paris', '2025-06-21', '2025-06-21', 'Concerts gratuits dans toute la ville. Tous les styles musicaux représentés.', 30438, 2),
(3, 'Feria de Nîmes', '2025-05-15', '2025-05-19', 'Grande fête taurine avec corridas, concerts, bodega. Ambiance festive garantie !', 22127, 5),
(4, 'Jazz à Vienne', '2025-06-27', '2025-07-12', 'Festival international de jazz dans le théâtre antique. Artistes de renommée mondiale.', 19746, 2),
(5, 'Festival d\'Avignon', '2025-07-05', '2025-07-26', 'Le plus grand festival de théâtre et des arts du spectacle vivant au monde.', 22127, 4),
(6, 'Braderie de Lille', '2025-09-06', '2025-09-07', 'Plus grand marché aux puces d\'Europe. Brocante, restauration, animations.', 27422, 6),
(7, 'Marché de Noël Strasbourg', '2025-11-28', '2025-12-24', 'Le plus ancien marché de Noël de France. Artisanat, gastronomie alsacienne, animations.', 32195, 6),
(8, 'Les Nuits de Fourvière', '2025-06-01', '2025-07-31', 'Festival pluridisciplinaire dans les théâtres romains de Lyon. Concerts, danse, théâtre.', 19746, 4),
(9, 'Festival Interceltique Lorient', '2025-08-01', '2025-08-10', 'Célébration des cultures celtes. Concerts, bagadoù, danses traditionnelles.', 20158, 1),
(10, 'Fête du Citron Menton', '2025-02-15', '2025-03-05', 'Spectaculaire défilé de chars décorés d\'agrumes. Thème renouvelé chaque année.', 1816, 1);
