INSERT INTO `pts_interet` (`id_pts_interet`, `lib_pts_interet`, `description_pts_interet`, `id_type_points_interet`, `id_commune`, `rue_pts_interet`) VALUES
(1, 'Tour Eiffel', 'Monument emblématique de Paris et symbole de la France. Vue panoramique exceptionnelle sur la capitale.', 1, 30438, 'Champ de Mars, 5 Avenue Anatole France'),
(2, 'Musée du Louvre', 'Le plus grand musée d\'art au monde. Abrite la Joconde et des milliers d\'œuvres d\'art.', 2, 30438, 'Rue de Rivoli'),
(3, 'Vieux Port de Marseille', 'Cœur historique de Marseille, lieu animé avec restaurants et boutiques. Point de départ pour les îles du Frioul.', 9, 4440, 'Quai du Port'),
(4, 'Basilique Notre-Dame de la Garde', 'Basilique emblématique dominant Marseille. Vue imprenable sur la ville et la Méditerranée.', 1, 4440, 'Rue Fort du Sanctuaire'),
(5, 'Parc de la Tête d\'Or', 'Plus grand parc urbain de France avec zoo gratuit, roseraie et lac. Idéal pour les familles.', 7, 19746, '69006 Lyon'),
(6, 'Musée des Confluences', 'Musée des sciences et des sociétés à l\'architecture moderne spectaculaire. Expositions permanentes et temporaires.', 2, 19746, '86 Quai Perrache'),
(7, 'Place du Capitole', 'Place centrale de Toulouse, cœur de la ville rose. Architecture magnifique et animations régulières.', 1, 31978, 'Place du Capitole'),
(8, 'Cité de l\'Espace', 'Parc à thème sur l\'espace et l\'astronomie. Expériences interactives, planétarium et expositions.', 5, 31978, 'Avenue Jean Gonord'),
(9, 'Promenade des Anglais', 'Célèbre promenade en bord de mer de Nice. Idéale pour se promener, faire du vélo ou du roller.', 4, 1816, 'Promenade des Anglais'),
(10, 'Château de Nice', 'Parc sur la colline du château offrant la plus belle vue sur Nice et la baie des Anges. Cascade artificielle.', 1, 1816, 'Montée du Château'),
(11, 'Plage de Biarritz', 'Magnifique plage de sable fin sur la côte basque. Spot de surf réputé, ambiance conviviale.', 4, 23695, 'Avenue de la Plage'),
(12, 'Rocher de la Vierge', 'Monument emblématique de Biarritz relié à la côte par une passerelle. Vue spectaculaire sur l\'océan.', 1, 23695, 'Esplanade du Rocher de la Vierge'),
(13, 'Lac d\'Annecy', 'Lac alpin aux eaux cristallines, considéré comme le plus pur d\'Europe. Activités nautiques et randonnées.', 7, 32716, 'Lac d\'Annecy'),
(14, 'Château d\'Annecy', 'Ancien château des comtes de Genève, aujourd\'hui musée. Architecture médiévale remarquable.', 1, 32716, 'Place du Château'),
(15, 'Cathédrale de Strasbourg', 'Chef-d\'œuvre de l\'art gothique avec sa célèbre horloge astronomique. Flèche culminant à 142 mètres.', 1, 32195, 'Place de la Cathédrale');
