INSERT INTO `reviews` (`id_review`, `id_biens`, `id_locataire`, `rating`, `content`, `created_at`, `user_type`, `validated`, `validated_by`, `validated_at`) VALUES
(1, 1, 1, 5, 'Appartement exceptionnel avec une vue magnifique sur la Tour Eiffel ! L\'emplacement est parfait, proche du métro et des commerces. Très bien équipé et propre. Je recommande vivement !', '2024-07-09 10:30:00', 'locataire', 1, 3, '2025-12-15 15:11:50'),
(2, 2, 2, 5, 'Villa de rêve ! La piscine est superbe, la vue mer incroyable. Les enfants ont adoré. Propriétaire très accueillant. Nous reviendrons sans hésiter.', '2024-08-18 14:15:00', 'locataire', 1, 3, '2025-12-15 15:11:43'),
(3, 3, 3, 4, 'Loft très sympa dans le vieux Lyon. Le quartier est animé avec beaucoup de restaurants. Seul bémol : un peu bruyant le week-end. Sinon parfait !', '2024-06-23 09:45:00', 'locataire', 1, 3, '2025-12-15 15:12:02'),
(4, 4, 4, 5, 'Maison magnifique, parfaite pour visiter les vignobles bordelais. Jardin agréable, maison très confortable. Excellente semaine !', '2024-09-13 16:20:00', 'locataire', 1, 3, '2025-12-15 15:11:33'),
(5, 5, 5, 4, 'Petit studio bien situé à Nice. Vue mer depuis le balcon, très appréciable. Un peu petit pour 2 personnes qui restent longtemps, mais parfait pour un week-end.', '2024-10-09 11:00:00', 'locataire', 1, 3, '2025-12-15 15:11:23'),
(6, 6, 6, 5, 'Chalet authentique avec une vue à couper le souffle sur le lac d\'Annecy. Parfait pour les randonnées. Très bien équipé, nous avons passé un séjour merveilleux.', '2024-12-28 18:30:00', 'locataire', 1, 3, '2025-12-15 15:11:08'),
(7, 1, 3, 5, 'Deuxième séjour dans cet appartement et toujours aussi ravi ! Paris est magnifique depuis cette fenêtre. Merci !', '2024-11-15 20:10:00', 'locataire', 1, 3, '2025-12-15 15:11:14'),
(8, 2, 4, 4, 'Villa superbe mais un peu loin du centre-ville. Nécessite une voiture. Sinon, tout était parfait, piscine chauffée très agréable.', '2024-09-25 13:45:00', 'locataire', 1, 3, '2025-12-15 15:11:29'),
(9, 7, 7, 5, 'Penthouse de luxe exceptionnel ! Vue panoramique incroyable. Équipements haut de gamme. Un séjour inoubliable à Marseille.', '2024-11-20 15:30:00', 'locataire', 1, 3, '2025-12-15 15:11:12'),
(10, 8, 8, 5, 'Cottage charmant en pleine Provence. Le jardin avec les oliviers est magnifique. Très calme, parfait pour se ressourcer.', '2024-10-05 12:00:00', 'locataire', 1, 3, '2025-12-15 15:11:26'),
(11, 9, 9, 4, 'Appartement bien situé place du Capitole. Pratique pour visiter Toulouse à pied. Quelques nuisances sonores la nuit mais gérable.', '2024-08-30 09:15:00', 'locataire', 1, 3, '2025-12-15 15:11:40'),
(12, 10, 10, 5, 'Villa basque splendide ! Architecture typique, très beau jardin, et à 2 minutes de la plage. Parfait pour des vacances en famille.', '2024-07-22 17:45:00', 'locataire', 1, 3, '2025-12-15 15:11:48'),
(13, 3, 5, 5, 'Lyon est magnifique et ce loft est idéal pour découvrir la ville. Cachet exceptionnel avec les pierres et poutres. Coup de cœur !', '2024-09-10 14:20:00', 'locataire', 1, 3, '2025-12-15 15:11:37'),
(14, 4, 6, 4, 'Belle maison à Bordeaux. Proche des transports pour visiter les châteaux. Jardin agréable. Bon rapport qualité-prix.', '2024-10-18 11:30:00', 'locataire', 1, 3, '2025-12-15 15:11:21'),
(15, 11, 1, 4, 'Loft sympa à Strasbourg, quartier très pittoresque. Parfait pour découvrir l\'Alsace. Aurait mérité une petite mise à jour de la déco.', '2024-11-05 10:00:00', 'locataire', 1, 3, '2025-12-15 15:11:17');
